#!/usr/bin/env python3
"""Exact ledger for the heat cocycle generated by a degree -1 swirl.

The script certifies rational exponents, radical identities, cocycle algebra,
and the two encoded iterated-limit values.  It does not solve or simulate
Navier--Stokes; the generating field U is not asserted to solve that PDE.
"""

from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction as Q
from hashlib import sha256
from math import isqrt
from pathlib import Path


class Audit:
    def __init__(self) -> None:
        self.assertions = 0

    def equal(self, left: object, right: object) -> None:
        self.assertions += 1
        assert left == right, (left, right)

    def true(self, statement: bool) -> None:
        self.assertions += 1
        assert statement


def squarefree_decomposition(value: int) -> tuple[int, int]:
    """Return outside, squarefree with sqrt(value)=outside*sqrt(squarefree)."""
    assert value >= 0
    if value == 0:
        return 0, 1
    outside = 1
    squarefree = value
    factor = 2
    while factor * factor <= squarefree:
        square = factor * factor
        while squarefree % square == 0:
            outside *= factor
            squarefree //= square
        factor += 1
    return outside, squarefree


@dataclass(frozen=True)
class RadicalSum:
    """A small exact vector space over Q generated by square roots of ints."""

    terms: tuple[tuple[int, Q], ...]

    @staticmethod
    def from_mapping(mapping: dict[int, Q]) -> "RadicalSum":
        cleaned = tuple(sorted((rad, coeff) for rad, coeff in mapping.items() if coeff))
        return RadicalSum(cleaned)

    @staticmethod
    def zero() -> "RadicalSum":
        return RadicalSum(())

    def __add__(self, other: "RadicalSum") -> "RadicalSum":
        merged = dict(self.terms)
        for radicand, coefficient in other.terms:
            merged[radicand] = merged.get(radicand, Q(0)) + coefficient
        return RadicalSum.from_mapping(merged)

    def __neg__(self) -> "RadicalSum":
        return RadicalSum(tuple((rad, -coefficient) for rad, coefficient in self.terms))

    def __sub__(self, other: "RadicalSum") -> "RadicalSum":
        return self + (-other)

    def scale(self, coefficient: Q) -> "RadicalSum":
        return RadicalSum.from_mapping(
            {rad: coefficient * value for rad, value in self.terms}
        )


def sqrt_int(value: int) -> RadicalSum:
    outside, squarefree = squarefree_decomposition(value)
    if outside == 0:
        return RadicalSum.zero()
    return RadicalSum(((squarefree, Q(outside)),))


def transition_bracket(first_time: int, second_time: int) -> RadicalSum:
    """Radial energy bracket, with the common positive factor removed."""
    assert first_time >= 0 and second_time >= 0
    return (
        sqrt_int(first_time + second_time).scale(Q(2))
        - sqrt_int(2 * first_time)
        - sqrt_int(2 * second_time)
    )


def audit_distributional_field(audit: Audit) -> None:
    # Away from zero:
    # d_1(-x_2/r^2)=+2*x_1*x_2/r^4 and
    # d_2(+x_1/r^2)=-2*x_1*x_2/r^4.
    audit.equal(Q(2) + Q(-2), Q(0))

    # On every centered sphere U.n=(-x_2*x_1+x_1*x_2)/r^3=0, so no
    # distributional point source is hidden at the origin.
    audit.equal(Q(-1) + Q(1), Q(0))

    # Exact distribution and local-energy coefficients, after removing pi.
    # K_3(U)^3=pi^2/4 and integral_(B_R)|U|^2=(8*pi/3)R.
    audit.equal(Q(1, 3) * 2 * Q(3, 8), Q(1, 4))
    audit.equal(Q(8, 3), Q(8, 3))

    # U is not a stationary unforced Navier--Stokes solution.  Away from
    # zero, Delta U=-2*U/r^2, whereas (U.grad)U is purely cylindrical-radial.
    # The viscous azimuthal residual has circulation coefficient 4*pi on a
    # circle (times the positive geometric factor s^2/r^4), so it cannot be
    # a single-valued pressure gradient.
    audit.equal(Q(2) * Q(2), Q(4))
    audit.true(Q(4) > 0)


def audit_heat_scaling(audit: Audit) -> None:
    # G_h contributes h^-3/2, dy contributes h^3/2, and degree -1
    # homogeneity contributes h^-1/2.
    kernel = Q(-3, 2)
    jacobian = Q(3, 2)
    homogeneous_field = Q(-1, 2)
    heat_amplitude = kernel + jacobian + homogeneous_field
    audit.equal(heat_amplitude, Q(-1, 2))

    # D_h=(I-S(h))U has the same similarity amplitude.  Its L2-square
    # exponent is -1+3/2=1/2, hence its L2 exponent is 1/4.
    l2_square = 2 * heat_amplitude + jacobian
    audit.equal(l2_square, Q(1, 2))
    audit.equal(l2_square / 2, Q(1, 4))

    # Fourier-side finiteness.  U-hat has magnitude rho^-2.
    spectral_field = Q(-2)
    radial_measure = Q(2)
    low_multiplier = Q(2)  # 1-exp(-h*rho^2) is order rho^2.
    low_radial_integrand = 2 * (spectral_field + low_multiplier) + radial_measure
    high_radial_integrand = 2 * spectral_field + radial_measure
    audit.equal(low_radial_integrand, Q(2))
    audit.equal(high_radial_integrand, Q(-2))
    audit.true(low_radial_integrand > -1)
    audit.true(high_radial_integrand < -1)

    # For h=m^4, ||D_h||_2/C_U=m and ||D_h||_2^2/C_U^2=m^2.
    for multiplier in (1, 2, 3, 5, 8, 13, 32, 128):
        time = multiplier**4
        audit.equal((multiplier**2) ** 2, time)
        audit.equal(isqrt(time), multiplier**2)


def audit_radical_energy(audit: Audit) -> None:
    base = transition_bracket(0, 1)  # 2-sqrt(2), strictly positive.
    audit.equal(base, sqrt_int(1).scale(Q(2)) - sqrt_int(2))

    # E(0,m^2) has bracket m*(2-sqrt(2)); this is the exact square-norm
    # scaling E(0,h)=C_U^2*sqrt(h).
    for multiplier in (1, 2, 3, 5, 8, 13, 32, 128):
        audit.equal(
            transition_bracket(0, multiplier**2),
            base.scale(Q(multiplier)),
        )

    # Symmetry and exact vanishing on the diagonal.
    for first, second in ((0, 1), (1, 4), (4, 9), (9, 25), (25, 64), (64, 169)):
        audit.equal(transition_bracket(first, second), transition_bracket(second, first))
        audit.equal(transition_bracket(first, first), RadicalSum.zero())

        # Positivity proof for square times: after squaring the two positive
        # sides, the gap is 2*(sqrt(first)-sqrt(second))^2.
        first_root = isqrt(first)
        second_root = isqrt(second)
        audit.equal(first_root**2, first)
        audit.equal(second_root**2, second)
        audit.true(first == second or 2 * (first_root - second_root) ** 2 > 0)


def audit_cocycle(audit: Audit) -> None:
    """Exact scalar-multiplier audit of D_h=(I-S(h))U."""
    rational_multipliers = (Q(1, 2), Q(2, 3), Q(3, 4), Q(4, 5), Q(7, 8))
    triples = ((1, 1, 1), (1, 2, 3), (2, 3, 5), (3, 5, 8), (5, 8, 13))
    for semigroup_unit in rational_multipliers:
        for first, second, third in triples:
            defect = lambda duration: 1 - semigroup_unit**duration
            direct = defect(first + second + third)
            expanded = (
                defect(first)
                + semigroup_unit**first * defect(second)
                + semigroup_unit ** (first + second) * defect(third)
            )
            left_parenthesized = defect(first + second) + semigroup_unit ** (
                first + second
            ) * defect(third)
            right_parenthesized = defect(first) + semigroup_unit**first * (
                defect(second) + semigroup_unit**second * defect(third)
            )
            audit.equal(direct, expanded)
            audit.equal(direct, left_parenthesized)
            audit.equal(direct, right_parenthesized)


def audit_uniformity_and_limit_order(audit: Audit) -> None:
    # Base time -T to observation time zero: ||D_T||_2/C_U=T^(1/4).
    previous_ratio = None
    for root in (1, 2, 3, 5, 8, 13, 32, 128):
        base_distance = root**4
        norm_ratio = Q(root)
        audit.equal(norm_ratio**4, Q(base_distance))
        if previous_ratio is not None:
            audit.true(norm_ratio > previous_ratio)
        previous_ratio = norm_ratio

    # Encoded analytically proved iterated limits for
    # R^-1*||D_T||_(L2(B_R))^2, with the factor pi removed:
    # space first gives 0 because D_T is globally L2 for fixed T;
    # base first gives 8/3 because D_T -> U locally in L2.
    space_then_base_over_pi = Q(0)
    base_then_space_over_pi = Q(8, 3)
    audit.equal(space_then_base_over_pi, Q(0))
    audit.equal(base_then_space_over_pi, Q(8, 3))
    audit.true(space_then_base_over_pi != base_then_space_over_pi)


def main() -> None:
    audit = Audit()
    audit_distributional_field(audit)
    audit_heat_scaling(audit)
    audit_radical_energy(audit)
    audit_cocycle(audit)
    audit_uniformity_and_limit_order(audit)

    source_hash = sha256(Path(__file__).read_bytes()).hexdigest()
    print("heat_cocycle_audit: PASS")
    print(f"exact_assertions={audit.assertions}")
    print("field=distributionally_divergence_free; K3_cube=pi^2/4")
    print("scaling=S(h)U(x)=h^-1/2*(S(1)U)(x/sqrt(h))")
    print("defect=||(I-S(h))U||_2=C_U*h^1/4 with 0<C_U<infinity")
    print("cocycle=D_(h+k+l)=D_h+S(h)D_k+S(h+k)D_l")
    print("transition_energy=exact_radical_bracket_certified")
    print("uniformity=sup_T||(I-S(T))U||_2=infinity")
    print("limit_order_over_pi=space_then_base:0, base_then_space:8/3")
    print("scope=heat-semigroup ledger for a kinematic field; U is not an NS solution")
    print(f"sha256_self={source_hash}")


if __name__ == "__main__":
    main()
